// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        uint256 a = bound(amount, 1 wei, 10 ether);
        PaySwitch payer = new PaySwitch(c);
        vm.deal(address(this), a);
        payer.deposit{value: a}();
        // make the external payout call fail
        payer.setFail(true);
        bool ok1 = payer.withdraw();
        // now allow payouts and drain whatever credit remains
        payer.setFail(false);
        payer.withdraw();
        // General rule: a SUCCESSFUL withdrawAll must actually pay out the full
        // credited amount (recording callee received exactly the credit).
        assertTrue(!ok1 || payer.received() == a, "successful withdrawAll must pay out full credit");
    }
}

contract PaySwitch {
    ReentrancyDAO c;
    bool public shouldFail;
    uint public received;
    constructor(ReentrancyDAO _c) { c = _c; }
    function setFail(bool f) external { shouldFail = f; }
    function deposit() external payable { c.deposit{value: msg.value}(); }
    function withdraw() external returns (bool) {
        bool ok; try c.withdrawAll() { ok = true; } catch { ok = false; }
        return ok;
    }
    receive() external payable {
        if (shouldFail) revert();
        received += msg.value;
    }
}
